import{}from"./core.min.js";import{api as t,esc as e,lineIcon as a,fmtDate as s,toast as n,promptBox as l,openModal as i,$ as c}from"./core.min.js";export async function lmsAdminPage(d){let o,r;d.innerHTML='<div class="skel" style="height:260px"></div>';try{[o,r]=await Promise.all([t("/api/admin/classes"),t("/api/admin/licenses")])}catch(t){return void(d.innerHTML=`<div class="sheet empty"><b>Không tải được</b>${e(t.message)}</div>`)}const h={active:["Còn hạn","tag-la"],expired:["Hết hạn","tag-line"],revoked:["Đã thu hồi","tag-do"]},m={active:["Đang mở","tag-la"],closed:["Đã đóng","tag-line"],archived:["Lưu trữ","tag-line"]};d.innerHTML=`\n    <section class="sheet sheet-pad" style="margin-bottom:16px">\n      <div class="sec-head"><div><h2>Giấy phép Teacher</h2><p>Giấy phép mua qua đơn hàng được cấp tự động. Cấp tay cho trường học/hợp đồng báo giá riêng (gói School).</p></div><button class="btn btn-primary btn-sm" id="grant">${a("plus")}Cấp giấy phép</button></div>\n      ${r.licenses.length?`<div class="table-wrap" style="border:0"><table><thead><tr><th>Giáo viên</th><th>Mức</th><th class="num">Chỗ đã dùng</th><th>Hiệu lực</th><th>Nguồn</th><th>Trạng thái</th><th></th></tr></thead><tbody>\n        ${r.licenses.map(t=>`<tr><td><b>${e(t.displayName)}</b><br><span class="small muted">@${e(t.username)}</span></td><td>${e(t.tier)}</td><td class="num">${t.used}/${t.seats}</td><td class="small">${s(t.startsAt,!1)} → ${s(t.expiresAt,!1)}</td><td class="small">${"admin"===t.source?"Cấp tay":"Đơn hàng"}${t.note?`<br><span class="muted">${e(t.note)}</span>`:""}</td><td><span class="tag ${h[t.status][1]}">${h[t.status][0]}</span></td>\n          <td>${"active"===t.status?`<button class="btn btn-xs btn-ghost" data-revoke="${t.id}" data-n="${e(t.username)}">Thu hồi</button>`:""}</td></tr>`).join("")}</tbody></table></div>`:'<p class="muted">Chưa có giấy phép nào.</p>'}\n    </section>\n    <section class="sheet sheet-pad">\n      <div class="sec-head"><div><h2>Tất cả lớp học</h2><p>Quản trị viên xem và quản lý mọi lớp, phân công lại giáo viên phụ trách.</p></div><button class="btn btn-sm" id="newClass">${a("plus")}Tạo lớp cho giáo viên</button></div>\n      ${o.classes.length?`<div class="table-wrap" style="border:0"><table><thead><tr><th>Lớp</th><th>Giáo viên</th><th class="num">Học sinh</th><th>Mã</th><th>Trạng thái</th><th></th></tr></thead><tbody>\n        ${o.classes.map(t=>`<tr><td><a href="/app/giao-vien/lop/${t.id}"><b>${e(t.name)}</b></a><br><span class="small muted">tạo ${s(t.createdAt,!1)}</span></td><td>${e(t.teacherName)}<br><span class="small muted">@${e(t.teacherUsername)}</span></td><td class="num">${t.members}</td><td><code>${e(t.joinCode)}</code></td><td><span class="tag ${m[t.status][1]}">${m[t.status][0]}</span></td>\n          <td>${"archived"!==t.status?`<button class="btn btn-xs" data-assign="${t.id}" data-teacher="${t.teacherId}">Đổi giáo viên</button>`:""}</td></tr>`).join("")}</tbody></table></div>`:'<p class="muted">Chưa có lớp nào.</p>'}\n    </section>`;const p=t=>o.teachers.map(a=>`<option value="${a.id}" ${a.id===t?"selected":""}>${e(a.displayName)} (@${e(a.username)}) · ${"admin"===a.role?"quản trị":"giáo viên"}</option>`).join("");c("#grant",d).addEventListener("click",()=>{const e=i('<h2>Cấp giấy phép Teacher</h2><form class="auth-form" data-f>\n      <label class="field">Tên đăng nhập của giáo viên<input name="u" required autocomplete="off"><small>Tài khoản học viên/phụ huynh sẽ tự thành giáo viên.</small></label>\n      <div class="grid-2"><label class="field">Số chỗ học sinh<input name="seats" type="number" min="1" max="5000" value="30" required></label><label class="field">Số tháng<input name="months" type="number" min="1" max="36" value="12" required></label></div>\n      <label class="field">Lý do / số hợp đồng<input name="note" required minlength="3" maxlength="300" placeholder="Ví dụ: HĐ 12/2026 Trường THPT A"></label>\n      <p class="form-msg err" data-m></p><div class="modal-actions"><button type="button" class="btn" data-close>Hủy</button><button class="btn btn-primary">Cấp giấy phép</button></div></form>');e.el.querySelector("[data-f]").addEventListener("submit",async a=>{a.preventDefault();const s=a.target;try{await t("/api/admin/licenses","POST",{username:s.u.value.trim(),seats:Number(s.seats.value),months:Number(s.months.value),note:s.note.value}),e.close(),n("Đã cấp giấy phép.","ok"),lmsAdminPage(d)}catch(t){e.el.querySelector("[data-m]").textContent=t.message}})}),c("#newClass",d).addEventListener("click",()=>{const e=i(`<h2>Tạo lớp cho giáo viên</h2><form class="auth-form" data-f><label class="field">Tên lớp<input name="name" required maxlength="80"></label><label class="field">Giáo viên phụ trách<select name="t">${p()}</select></label>\n      <p class="form-msg err" data-m></p><div class="modal-actions"><button type="button" class="btn" data-close>Hủy</button><button class="btn btn-primary">Tạo lớp</button></div></form>`);e.el.querySelector("[data-f]").addEventListener("submit",async a=>{a.preventDefault();try{await t("/api/classes","POST",{name:a.target.name.value,teacherId:Number(a.target.t.value)}),e.close(),n("Đã tạo lớp.","ok"),lmsAdminPage(d)}catch(t){e.el.querySelector("[data-m]").textContent=t.message}})}),d.querySelectorAll("[data-assign]").forEach(e=>e.addEventListener("click",()=>{const a=i(`<h2>Đổi giáo viên phụ trách</h2><form class="auth-form" data-f><label class="field">Giáo viên<select name="t">${p(Number(e.dataset.teacher))}</select><small>Học sinh giữ chỗ theo giấy phép của giáo viên mới khi tham gia hoặc được duyệt sau này.</small></label>\n      <p class="form-msg err" data-m></p><div class="modal-actions"><button type="button" class="btn" data-close>Hủy</button><button class="btn btn-primary">Lưu</button></div></form>`);a.el.querySelector("[data-f]").addEventListener("submit",async s=>{s.preventDefault();try{await t(`/api/classes/${e.dataset.assign}`,"PUT",{teacherId:Number(s.target.t.value)}),a.close(),n("Đã phân công.","ok"),lmsAdminPage(d)}catch(t){a.el.querySelector("[data-m]").textContent=t.message}})})),d.querySelectorAll("[data-revoke]").forEach(e=>e.addEventListener("click",async()=>{const a=await l(`Thu hồi giấy phép của @${e.dataset.n}?`,"Giáo viên không tạo lớp mới được; học sinh trong lớp mất quyền Pro từ giấy phép này (Pro cá nhân/Family giữ nguyên). Ghi lý do:",{label:"Lý do",okLabel:"Thu hồi",validate:t=>t.trim().length>=3?"":"Ít nhất 3 ký tự"});if(a)try{await t(`/api/admin/licenses/${e.dataset.revoke}/revoke`,"POST",{note:a}),n("Đã thu hồi.","ok"),lmsAdminPage(d)}catch(t){n(t.message,"err")}}))}